"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, useId, useMemo, useState } from "react";

import { cn } from "@/lib/utils";

/** One part of the context window, such as the files a person attached. */
export interface ContextSegment {
  id: string;
  label: string;
  tokens: number;
  /** A background class for the segment, such as `bg-chart-2`. Defaults to a chart token by position. */
  tone?: string;
}

/** Props for a bar that shows how full a model's context window is, part by part. */
export type ContextMeterProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  /** The parts in use, in the order the bar draws them from the left. */
  segments: ContextSegment[];
  /** The size of the context window, in tokens. */
  limit: number;
  label?: string;
  /** The legend name for the unused part. */
  freeLabel?: string;
  /** The share in use, from 0 to 1, at which the warning shows. */
  warnAt?: number;
  warningLabel?: string;
  /** A BCP 47 locale such as "en-GB". It defaults to "en-US", so the server and the browser render the same text. */
  locale?: string;
};

// Damping 35 is above 2 × √300, so a segment grows to its new size without overshoot.
const GROW: Transition = { type: "spring", stiffness: 300, damping: 35, mass: 1 };
const INSTANT: Transition = { duration: 0 };

const TONES = ["bg-chart-1", "bg-chart-2", "bg-chart-4", "bg-chart-5", "bg-chart-3"];
// Unused space has its own key, and each part's key carries a prefix, so a part a caller names "free" never collides with it.
const FREE = "free-space";
const keyOf = (id: string) => `segment:${id}`;

function WarningGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4 shrink-0 text-destructive">
      <path
        fillRule="evenodd"
        d="M6.7 2.25a1.5 1.5 0 0 1 2.6 0l5 8.75A1.5 1.5 0 0 1 13 13.25H3A1.5 1.5 0 0 1 1.7 11l5-8.75ZM8 5.25c.41 0 .75.34.75.75v2.5a.75.75 0 0 1-1.5 0V6c0-.41.34-.75.75-.75Zm0 6.5a.9.9 0 1 0 0-1.8.9.9 0 0 0 0 1.8Z"
      />
    </svg>
  );
}

/**
 * Shows how full a model's context window is as one stacked bar, with a legend
 * that names each part and its token count. When the parts change, each one
 * grows or shrinks from the left. Above the warning share, an icon and a short
 * text say so.
 */
export function ContextMeter({
  segments,
  limit,
  label = "Context window",
  freeLabel = "Free",
  warnAt = 0.8,
  warningLabel = "Nearly full",
  locale = "en-US",
  className,
  ...divProps
}: ContextMeterProps) {
  const reduceMotion = useReducedMotion();
  const labelId = useId();
  const [pointed, setPointed] = useState<string | null>(null);
  const compact = useMemo(() => new Intl.NumberFormat(locale, { notation: "compact", maximumFractionDigits: 1 }), [locale]);
  const full = useMemo(() => new Intl.NumberFormat(locale), [locale]);

  const room = Math.max(limit, 1);
  const parts = segments.map((segment, index) => ({
    ...segment,
    tokens: Math.max(segment.tokens, 0),
    tone: segment.tone ?? TONES[index % TONES.length],
  }));
  const used = parts.reduce((sum, part) => sum + part.tokens, 0);
  const percent = Math.round((used / room) * 100);
  const warning = used / room >= warnAt;

  // Each bar runs from the left edge to the end of its part, and an earlier
  // bar covers a later one. A bar then grows with a scale alone, and the
  // browser never lays the row out again while it moves.
  let end = 0;
  const bars = parts.map((part) => {
    end += part.tokens;
    return { ...part, scaleX: Math.min(end / room, 1) };
  });

  const legend = [
    ...parts.map((part) => ({ id: keyOf(part.id), label: part.label, tokens: part.tokens, swatch: part.tone })),
    { id: FREE, label: freeLabel, tokens: Math.max(limit - used, 0), swatch: "border border-border bg-muted" },
  ];

  return (
    <div {...divProps} className={cn("flex w-full flex-col gap-3", className)}>
      <div className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
        <p className="flex items-baseline gap-2 text-sm">
          <span id={labelId} className="font-medium text-foreground">
            {label}
          </span>
          <span className="text-muted-foreground tabular-nums">
            {compact.format(used)} of {compact.format(limit)} tokens
          </span>
        </p>
        <p className="flex items-center gap-2 text-sm font-medium text-foreground tabular-nums">
          {/* The region stays in the page, so a screen reader hears the warning when it appears. */}
          <span role="status" className="inline-flex items-center gap-1.5">
            {warning ? (
              <>
                <WarningGlyph />
                {warningLabel}
              </>
            ) : null}
          </span>
          <span>{percent}% used</span>
        </p>
      </div>
      <div
        role="meter"
        aria-labelledby={labelId}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={Math.min(percent, 100)}
        aria-valuetext={`${percent}% used, ${full.format(used)} of ${full.format(limit)} tokens${warning ? `, ${warningLabel}` : ""}`}
        data-warning={warning}
        onPointerLeave={() => setPointed(null)}
        className={cn(
          "relative h-3 w-full overflow-hidden rounded-full bg-muted motion-safe:transition-shadow motion-safe:duration-200",
          warning && "ring-2 ring-destructive/50",
        )}
      >
        <span aria-hidden="true" onPointerEnter={() => setPointed(FREE)} className="absolute inset-0" />
        {/* Later bars paint on top, so the list runs backwards: the first part, the shortest bar, sits in front. */}
        {[...bars].reverse().map((bar) => (
          <motion.span
            key={keyOf(bar.id)}
            aria-hidden="true"
            initial={false}
            animate={{ scaleX: bar.scaleX }}
            transition={reduceMotion ? INSTANT : GROW}
            onPointerEnter={() => setPointed(keyOf(bar.id))}
            className={cn("absolute inset-0 origin-left", bar.tone)}
          />
        ))}
      </div>
      {/* The negative margin lines the first swatch up with the bar, because each item carries its own padding. */}
      <ul className="-mx-2 flex flex-wrap gap-y-1">
        {legend.map((item) => (
          <li
            key={item.id}
            data-pointed={pointed === item.id}
            className="inline-flex items-center gap-1.5 rounded-full px-2 py-0.5 text-xs text-muted-foreground data-[pointed=true]:bg-muted motion-safe:transition-colors motion-safe:duration-150"
          >
            <span aria-hidden="true" className={cn("size-2 shrink-0 rounded-full", item.swatch)} />
            <span className="text-foreground">{item.label}</span>
            <span className="tabular-nums">{compact.format(item.tokens)}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}
